scenario = "SlidingWindowRateLimiter(limit=2, window=10) with a fake clock"
class FakeClock:
    """A clock the tests move by hand."""
    def __init__(self):
        self.now = 0.0

    def __call__(self):
        return self.now
def replay(limiter, requests):
    """Send each (time, key) request in order, setting the fake clock to that time first; return the list of answers."""
    answers = []
    for when, key in requests:
        clock.now = when
        answers.append(limiter.allow(key))
    return answers
def accepted(limiter, requests):
    """How many of the requests were allowed."""
    return replay(limiter, requests).count(True)
clock = FakeClock()
limiter = SlidingWindowRateLimiter(limit=2, window=10, clock=clock)
